fn lo(a: i32, b: i32) -> i32 {
    if a < b { a } else { b }
}

fn hi(a: i32, b: i32) -> i32 {
    if a > b { a } else { b }
}

fn clamp(v: i32, low: i32, high: i32) -> i32 {
    hi(low, lo(v, high))
}

fn lerp(a: i32, b: i32, n16: i32) -> i32 {
    a + (b - a) * n16 / 16
}

fn iabs(v: i32) -> i32 {
    if v < 0 { 0 - v } else { v }
}

fn dims() -> i32 {
    (256 << 16) | 96
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 8, "LIB MATH", 0xffffff, 2);
    host::display::draw_string(8, 32, "LO HI CLAMP", 0x00ff66, 1);
    host::display::draw_string(8, 46, "LERP IABS", 0x00ff66, 1);
    host::display::draw_string(8, 60, "SPAWN_LIB + CALL", 0x808080, 1);
    host::display::present();
}
